(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.012-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.015+t*0.28)*12;
  const w2x = Math.sin((x+y)*0.008+t*0.15)*8;
  const w2y = Math.cos((x-y)*0.009-t*0.12)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [60+Math.sin(t*0.7+3)*70, 40+Math.cos(t*0.45+4)*50, 0.11, 2.1],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.65+1)*40, 0.085, 2.4],
    [200+Math.sin(t*0.42+6)*90, 30+Math.cos(t*0.78)*60, 0.075, 1.8]
  ];
  let aS=0, iS=0, eF=0;
  for (const [sX,sY,f,sp] of src) {
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w=Math.sin(d*f-t*sp);
    aS+=w; iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    eF+=Math.sin(d*f*1.4-t*sp*0.8+2.0)*0.3;
  }
  const act=aS/9, inh=iS/9, edge=eF/9;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.07*Math.cos(t*0.1)+sy*0.05*Math.sin(t*0.15)+t*0.6)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.08-ang*6+t*2.0)*0.15;
  const micro=Math.sin(sx*0.3+act*2)*Math.sin(sy*0.3-inh*2)*0.12;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+micro)*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const edgeDetect=Math.tanh(edge*3.0)*0.2;
  const blend=reaction*0.6+cell*0.2+edgeDetect, v=blend*0.5+0.5;
  const hueShift=Math.sin(t*0.15)*0.08;
  const pal=[
    [6,12,58],[10,45,95],[18,90,115],[30,140,130],[90,170,120],
    [170,190,80],[210,175,65],[215,130,70],[190,80,65],[140,45,70],
    [85,25,65],[40,18,58],[6,12,58]
  ];
  let idx=v*(pal.length-1)+hueShift*(pal.length-1);
  idx=((idx%(pal.length-1))+(pal.length-1))%(pal.length-1);
  const i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const glow=Math.abs(reaction)>0.65?1.0+Math.abs(reaction)*0.2:1.0;
  const deep=Math.abs(reaction)<0.15?0.85:1.0;
  const m=lum*glow*deep;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0
  ];
}
